import { test, expect } from 'bun:test';
import { buildSearchQuery } from '../src/search.js';
test('no filters', () => expect(buildSearchQuery({})).toEqual({ sql: 'SELECT * FROM products', params: [] }));
test('all filters', () => {
  const q = buildSearchQuery({ name: 'shoe', minPrice: 1000, status: 'active' });
  expect(q.sql).toBe('SELECT * FROM products WHERE name LIKE ? AND price >= ? AND status = ?');
  expect(q.params).toEqual(['%shoe%', 1000, 'active']);
});
test('sorting', () => {
  expect(buildSearchQuery({ sortBy: 'price' }).sql).toBe('SELECT * FROM products ORDER BY price');
  expect(buildSearchQuery({ sortBy: 'name', desc: true }).sql).toBe('SELECT * FROM products ORDER BY name DESC');
});

