import { test, expect } from 'bun:test';
import { buildSearchQuery } from '../src/search.js';
test('values are bound, never spliced into the SQL', () => {
  const evil = "x'; DROP TABLE products; --";
  const q = buildSearchQuery({ name: evil, status: evil });
  expect(q.sql).not.toContain('DROP');
  expect(q.sql.split('?').length - 1).toBe(q.params.length);
  expect(q.params).toContain('%' + evil + '%');
});
test('sortBy cannot carry SQL', () => {
  expect(() => buildSearchQuery({ sortBy: 'price; DROP TABLE products' })).toThrow();
  expect(() => buildSearchQuery({ sortBy: '(SELECT 1)' })).toThrow();
  expect(buildSearchQuery({ sortBy: 'status' }).sql).toContain('ORDER BY status');
});
